(() => {
  const el=id=>document.getElementById(id), meeting=el('meeting'), room=meeting.querySelector('.room'), aside=meeting.querySelector('aside'), caption=room.querySelector('.caption');
  const workspace=document.createElement('div');workspace.className='lesson-workspace';room.insertBefore(workspace,el('tiles'));workspace.append(el('screenStage'),el('tiles'),caption);
  aside.id='lessonPanel';aside.hidden=true;
  const actions=document.createElement('div');actions.className='room-actions';
  const quick=document.createElement('button');quick.id='quickTranslate';quick.className='primary';quick.textContent='Ativar tradução';quick.onclick=()=>{if(el('prepareTranslate').disabled)return;panel(true);el('prepareTranslate').click()};
  const toggle=document.createElement('button');toggle.id='panelToggle';toggle.textContent='Conversa';toggle.setAttribute('aria-controls','lessonPanel');toggle.setAttribute('aria-expanded','false');
  actions.append(quick,toggle);room.querySelector('.roomhead').append(actions);
  function panel(open){aside.hidden=!open;meeting.classList.toggle('panel-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.classList.toggle('selected',open)}
  toggle.onclick=()=>panel(aside.hidden);
  const close=document.createElement('button');close.className='panel-close';close.textContent='Fechar painel ×';close.onclick=()=>panel(false);aside.prepend(close);
  const invite=room.querySelector('.invite'),details=document.createElement('details');details.className='invite-details';const summary=document.createElement('summary');summary.textContent='Convidar aluno';invite.before(details);details.append(summary,invite);
  caption.innerHTML='<div class="caption-heading"><div class="caption-identity"><strong>Conversa ao vivo</strong><span id="captionPhase">Cada voz tem seu espaço.</span></div><div class="caption-tools"><label>Letra<select id="captionSize" aria-label="Tamanho das legendas"><option value="18">Normal</option><option value="21">Grande</option><option value="26">Maior</option></select></label><label class="original-toggle"><input type="checkbox" id="showOriginal">Original</label><button id="expandCaption" aria-pressed="false">Mais texto</button><button id="floatingCaption">Legenda flutuante</button></div></div><div class="caption-bubbles"><article class="speech-bubble teacher-bubble empty-caption" id="teacherBubble" aria-live="polite" aria-atomic="true"><div class="bubble-head"><span class="bubble-avatar" id="teacherBubbleAvatar">P</span><strong class="bubble-name" id="captionSpeaker">Professora</strong><span class="bubble-role">PROFESSORA</span></div><p class="bubble-text" id="caption">Aguardando a professora…</p><small class="bubble-original" id="original" hidden></small><span class="bubble-status" id="teacherCaptionStatus">A fala dela fica aqui.</span></article><article class="speech-bubble student-bubble empty-caption" id="studentBubble" aria-live="polite" aria-atomic="true"><div class="bubble-head"><span class="bubble-avatar" id="studentBubbleAvatar">A</span><strong class="bubble-name" id="studentCaptionSpeaker">Aluno</strong><span class="bubble-role">ALUNO</span></div><p class="bubble-text" id="studentCaption">Aguardando o aluno…</p><small class="bubble-original" id="studentOriginal" hidden></small><span class="bubble-status" id="studentCaptionStatus">A resposta dele fica aqui.</span></article></div><span id="captionLanguage" class="caption-language"></span>';
  const size=el('captionSize'),originalToggle=el('showOriginal');
  try{const saved=localStorage.getItem('captionSize');size.value=['18','21','26'].includes(saved)?saved:'21';originalToggle.checked=localStorage.getItem('showOriginal')==='true'}catch{size.value='21'}
  let selfRole='teacher',pip,wasSharing=false;
  const lane=role=>role==='teacher'?{bubble:el('teacherBubble'),speaker:el('captionSpeaker'),text:el('caption'),original:el('original'),status:el('teacherCaptionStatus'),avatar:el('teacherBubbleAvatar')}:{bubble:el('studentBubble'),speaker:el('studentCaptionSpeaker'),text:el('studentCaption'),original:el('studentOriginal'),status:el('studentCaptionStatus'),avatar:el('studentBubbleAvatar')};
  function applyPreferences(){caption.style.setProperty('--caption-font',size.value+'px');for(const role of ['teacher','student']){const l=lane(role);l.original.hidden=!originalToggle.checked||!l.original.textContent}try{localStorage.setItem('captionSize',size.value);localStorage.setItem('showOriginal',String(originalToggle.checked))}catch{}updateFloating()}
  size.onchange=applyPreferences;originalToggle.onchange=applyPreferences;
  el('expandCaption').onclick=()=>{const expanded=caption.classList.toggle('caption-expanded');el('expandCaption').setAttribute('aria-pressed',String(expanded));el('expandCaption').textContent=expanded?'Menos texto':'Mais texto'};
  function syncLayout(){const sharing=!el('screenStage').hidden;meeting.classList.toggle('presenting',sharing);if(sharing&&!wasSharing){panel(false);details.open=false}if(!sharing){meeting.classList.remove('screen-focused');el('focusScreen').setAttribute('aria-pressed','false');el('focusScreen').textContent='Expandir tela'}wasSharing=sharing}
  new MutationObserver(syncLayout).observe(el('screenStage'),{attributes:true,attributeFilter:['hidden']});syncLayout();
  el('focusScreen').onclick=()=>{const focused=meeting.classList.toggle('screen-focused');el('focusScreen').setAttribute('aria-pressed',String(focused));el('focusScreen').textContent=focused?'Mostrar câmeras':'Expandir tela';if(focused)panel(false)};
  el('screenFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else{panel(false);await meeting.requestFullscreen()}}catch{el('captionPhase').textContent='Tela cheia indisponível neste navegador.'}};
  document.addEventListener('fullscreenchange',()=>{el('screenFullscreen').textContent=document.fullscreenElement?'Sair da tela cheia':'Tela cheia'});
  function updateFloating(){if(!pip||pip.closed)return;for(const role of ['teacher','student']){const l=lane(role);pip.document.getElementById(role+'Name').textContent=l.speaker.textContent;pip.document.getElementById(role+'Text').textContent=l.text.textContent;pip.document.getElementById(role+'Text').style.fontSize=size.value+'px'}}
  el('floatingCaption').onclick=async()=>{if(pip&&!pip.closed){pip.close();return}if(!window.documentPictureInPicture){el('captionPhase').textContent='Legenda flutuante disponível no Chrome compatível.';return}try{pip=await documentPictureInPicture.requestWindow({width:650,height:260});pip.document.title='Aula Global — conversa';pip.document.body.innerHTML='<style>body{font:14px Arial;margin:0;padding:16px;background:#f5f6f8;color:#202124;display:grid;grid-template-columns:1fr 1fr;gap:12px}article{background:white;border:1px solid #dadce0;border-top:3px solid #84b2ef;border-radius:12px;padding:12px}article+article{border-top-color:#b4a1d5}strong{font-size:12px}p{line-height:1.4;overflow-wrap:anywhere;max-height:160px;overflow:auto}</style><article><strong id="teacherName"></strong><p id="teacherText"></p></article><article><strong id="studentName"></strong><p id="studentText"></p></article>';pip.addEventListener('pagehide',()=>{pip=null;el('floatingCaption').textContent='Legenda flutuante'});el('floatingCaption').textContent='Fechar flutuante';updateFloating()}catch{el('captionPhase').textContent='Não foi possível abrir a legenda flutuante.'}};
  const paths={mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',camera:'<rect x="2" y="5" width="14" height="14" rx="3"/><path d="m16 10 6-4v12l-6-4"/>',share:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4m0-7V6m-3 3 3-3 3 3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',leave:'<path d="M3 15c5-5 13-5 18 0l-2 4-5-2v-3h-4v3l-5 2-2-4Z"/>'};
  function controlLabel(id,label){const b=el(id);b.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[id]+'</svg>';const span=document.createElement('span');span.className='control-text';span.textContent=label;b.append(span);b.setAttribute('aria-label',label);b.title=label}
  for(const id of Object.keys(paths))controlLabel(id,el(id).textContent);
  window.meetingUI={controlLabel};
  window.captionUI={
    set(name,text,originalText,language,status,role='teacher'){const l=lane(role);l.bubble.classList.remove('empty-caption');l.bubble.classList.toggle('pending',status.includes('pendente'));l.speaker.textContent=name;l.avatar.textContent=name[0]?.toUpperCase()||'?';l.text.textContent=text;l.original.textContent=originalText!==text?originalText:'';l.original.hidden=!originalToggle.checked||!l.original.textContent;l.status.textContent=status;l.text.title=text;el('captionLanguage').textContent=language;for(const tile of el('tiles').querySelectorAll('.tile'))if(tile.dataset.name===name||(tile.id==='selfTile'&&el('selfName').textContent===name))tile.classList.add('last-speaker');updateFloating()},
    configure(state){selfRole=state.you.role;const host=state.members.find(m=>m.role==='teacher'),student=state.members.find(m=>m.role==='student'&&m.status==='accepted');if(el('teacherBubble').classList.contains('empty-caption')&&host)el('captionSpeaker').textContent=host.name;if(el('studentBubble').classList.contains('empty-caption')&&student)el('studentCaptionSpeaker').textContent=student.name;details.hidden=selfRole!=='teacher';el('teacherLanguageSummary').hidden=selfRole!=='teacher';},
    phase(text,role=selfRole){lane(role).status.textContent=text;updateFloating()},openPanel:()=>panel(true),closeFloating(){pip?.close()}
  };
  // Keep technical recognition settings available on demand, outside the conversation.
  window.addEventListener('DOMContentLoaded',()=>{const advanced=document.createElement('details');advanced.className='recognition-settings';const title=document.createElement('summary');title.textContent='Opções de reconhecimento';advanced.append(title);for(const id of ['speechEngine','asrStatus','checkASR','autoPunctuation','punctuationStatus']){const node=el(id);if(node)advanced.append(node.closest('label')||node)}const cancel=[...document.querySelectorAll('.livebox button')].find(b=>b.textContent==='Cancelar preparação');if(cancel)advanced.append(cancel);document.querySelector('.livebox').append(advanced)});
  applyPreferences();window.addEventListener('pagehide',()=>pip?.close());
})();
